import fs from 'node:fs';
import path from 'node:path';
import { randomUUID } from 'node:crypto';
import type { Pool, QueryResultRow } from 'pg';
import { createSessionToken, hashPassword, hashPasswordSync, hashSessionToken, sessionExpiresAt } from './auth.js';
import { ACCOUNT_TOKEN_TTL_MS, createAccountToken as makeAccountToken, hashAccountToken, issueAccountToken } from './accountTokens.js';
import type { AccountTokenPurpose, AdminRole, AdminUser, AuditEvent, Campaign, CampaignApprovalStatus, CampaignReadiness, CampaignRevision, Customer, DeliveryContext, JobStatus, OaIntegration, OutboxDelivery, OutboxDeliveryStatus, QuotaReservation, SchedulerJob } from './types.js';
import { OaPolicyError } from './oaPolicy.js';
import { fillFlexTemplate } from './flexTemplate.js';

type StoredUser = AdminUser & { passwordHash: string; active: boolean; membershipStatus: 'INVITED' | 'ACTIVE' | 'SUSPENDED' };
type JobInput = { campaignId: string; oaId: string; scheduledAt: string; timeZone: string; status: 'DRAFT' | 'SCHEDULED'; mode?: 'DRY_RUN' | 'LIVE'; workspaceId: string; actor: string; clientRequestKey?: string };
type OaInput = { workspaceId: string; providerId: string; basicId: string; displayName: string; actor: string };
type OutboxResult = { providerStatus?: number; providerRequestId?: string };

export interface Repository {
  readonly kind: 'postgres' | 'memory';
  getUserByEmail(email: string): Promise<StoredUser | null>;
  createSession(userId: string): Promise<{ token: string; expiresAt: Date }>;
  getSessionUser(token: string): Promise<AdminUser | null>;
  revokeSession(token: string): Promise<void>;
  createAccountToken(input: { workspaceId: string; adminUserId: string; purpose: AccountTokenPurpose; actor: string; ttlMs?: number }): Promise<{ token: string; expiresAt: string }>;
  consumeAccountToken(token: string, password: string): Promise<AdminUser>;
  listCampaigns(workspaceId?: string): Promise<Campaign[]>;
  listOas(workspaceId?: string): Promise<OaIntegration[]>;
  listCustomers(workspaceId?: string): Promise<Customer[]>;
  listJobs(workspaceId?: string): Promise<SchedulerJob[]>;
  listOutbox(workspaceId?: string, jobId?: string): Promise<OutboxDelivery[]>;
  listAudit(workspaceId?: string): Promise<AuditEvent[]>;
  dashboard(workspaceId?: string): Promise<{ mode: 'DRY_RUN'; counts: Record<string, number>; nextJob: SchedulerJob | null }>;
  addJob(input: JobInput): Promise<SchedulerJob>;
  scheduleJob(id: string, actor: string, workspaceId: string): Promise<SchedulerJob>;
  pauseJob(id: string, actor: string, workspaceId: string): Promise<SchedulerJob>;
  resumeJob(id: string, actor: string, workspaceId: string): Promise<SchedulerJob>;
  cancelJob(id: string, actor: string, workspaceId: string): Promise<SchedulerJob>;
  retryJob(id: string, actor: string, workspaceId: string): Promise<SchedulerJob>;
  runDryRun(id: string, actor: string, workspaceId: string): Promise<SchedulerJob>;
  claimDueJob(workerId: string, now?: Date, jobId?: string): Promise<SchedulerJob | null>;
  markJobSending(id: string, workerId: string): Promise<SchedulerJob>;
  markJobCompleted(id: string, workerId: string): Promise<SchedulerJob>;
  markJobFailure(id: string, workerId: string, error: string, retryAt: Date | null): Promise<SchedulerJob>;
  prepareOutbox(jobId: string, workerId: string): Promise<OutboxDelivery[]>;
  getDeliveryContext(deliveryId: string, workspaceId: string): Promise<DeliveryContext>;
  reserveDeliverySlot(input: { workspaceId: string; oaId: string; count: boolean; now?: Date }): Promise<QuotaReservation>;
  releaseDeliverySlot(input: { workspaceId: string; oaId: string; windowStartedAt: string | null }): Promise<void>;
  reconcileOutboxDelivery(input: { jobId: string; deliveryId: string; workspaceId: string; status: 'SENT' | 'FAILED'; actor: string }): Promise<OutboxDelivery>;
  markOutboxSending(id: string, workerId: string): Promise<OutboxDelivery>;
  markOutboxCompleted(id: string, workerId: string, result: OutboxResult): Promise<OutboxDelivery>;
  markOutboxFailure(id: string, workerId: string, error: string, status: Exclude<OutboxDeliveryStatus, 'PENDING' | 'SENDING' | 'SENT' | 'SKIPPED'>, result?: OutboxResult): Promise<OutboxDelivery>;
  recoverStaleJobs(staleBefore: Date, now?: Date): Promise<number>;
  listRevisions(campaignId: string, workspaceId?: string): Promise<CampaignRevision[]>;
  createRevision(campaignId: string, flexJson: Record<string, unknown>, actor: string, workspaceId?: string): Promise<CampaignRevision>;
  acceptWebhook(input: { oaId: string; eventId: string; payloadHash: string; eventType?: string; lineUserKey?: string }): Promise<{ accepted: boolean; duplicate: boolean }>;
  createOa(input: OaInput): Promise<OaIntegration>;
  validateOa(id: string, workspaceId: string, actor: string): Promise<OaIntegration>;
  setOaKillSwitch(id: string, workspaceId: string, enabled: boolean, reason: string, actor: string): Promise<OaIntegration>;
  setOaEnabled(id: string, workspaceId: string, enabled: boolean, actor: string): Promise<OaIntegration>;
  setSystemKillSwitch(workspaceId: string, enabled: boolean, reason: string, actor: string): Promise<{ enabled: boolean; reason?: string }>;
  setCampaignKillSwitch(campaignId: string, workspaceId: string, enabled: boolean, reason: string, actor: string): Promise<CampaignReadiness>;
  validateCampaign(campaignId: string, workspaceId: string, actor: string): Promise<CampaignReadiness>;
  approveCampaign(campaignId: string, workspaceId: string, actor: string): Promise<CampaignReadiness>;
  getCampaignReadiness(campaignId: string, workspaceId: string, oaId?: string): Promise<CampaignReadiness>;
}

function readSeed() {
  const root = path.resolve(process.cwd());
  const manifest = JSON.parse(fs.readFileSync(path.join(root, 'campaigns.json'), 'utf8')) as { campaigns: Campaign[] };
  return manifest.campaigns.map((campaign) => ({ ...campaign, flexJson: fillFlexTemplate(campaign, JSON.parse(fs.readFileSync(path.join(root, campaign.flexFile), 'utf8')) as Record<string, unknown>), latestRevision: 1 }));
}

/** A campaign row with no saved revision still has to offer a card the operator can actually send. */
function bundledTemplate(campaign: Campaign) {
  try { return fillFlexTemplate(campaign, JSON.parse(fs.readFileSync(path.resolve(process.cwd(), campaign.flexFile), 'utf8')) as Record<string, unknown>); } catch { return undefined; }
}

function rowDate(value: unknown) { return (value instanceof Date ? value : new Date(String(value))).toISOString(); }
function normalizeStatus(value: string): JobStatus { if (value === 'QUEUED') return 'SCHEDULED'; if (value === 'CANCELED') return 'CANCELLED'; if (value === 'FAILED_FINAL') return 'FAILED'; return value as JobStatus; }
function mapJob(row: QueryResultRow): SchedulerJob { return { id: String(row.id), workspaceId: row.workspace_id ? String(row.workspace_id) : undefined, campaignId: String(row.campaign_id), campaignRevisionId: row.campaign_revision_id ? String(row.campaign_revision_id) : undefined, oaId: String(row.oa_id), scheduledAt: rowDate(row.scheduled_at), timeZone: String(row.time_zone || 'Asia/Bangkok'), availableAt: row.available_at ? rowDate(row.available_at) : undefined, mode: row.mode, status: normalizeStatus(String(row.status)), attempts: Number(row.attempts), idempotencyKey: String(row.idempotency_key), lastError: row.last_error ? String(row.last_error) : undefined, createdAt: rowDate(row.created_at) }; }
function mapOutbox(row: QueryResultRow): OutboxDelivery { return { id: String(row.id), workspaceId: String(row.workspace_id), jobId: String(row.scheduler_job_id), oaId: String(row.oa_integration_id), recipientKey: String(row.recipient_key), idempotencyKey: String(row.idempotency_key), lineRetryKey: String(row.line_retry_key), status: row.status as OutboxDeliveryStatus, attempts: Number(row.attempts), providerStatus: row.provider_status == null ? undefined : Number(row.provider_status), providerRequestId: row.provider_request_id ? String(row.provider_request_id) : undefined, lastError: row.last_error ? String(row.last_error) : undefined, createdAt: rowDate(row.created_at), updatedAt: rowDate(row.updated_at) }; }
function mapOa(row: QueryResultRow): OaIntegration { return { id: String(row.id), displayName: String(row.display_name), basicId: String(row.basic_id), providerId: String(row.provider_id), environment: row.environment, enabled: Boolean(row.enabled), secretConfigured: Boolean(row.secret_configured), connectionStatus: row.connection_status, credentialStatus: row.credential_status, quotaPerMinute: Number(row.quota_per_minute), killSwitch: Boolean(row.kill_switch), killSwitchReason: row.kill_switch_reason ? String(row.kill_switch_reason) : undefined }; }
function mapReadiness(row: QueryResultRow): CampaignReadiness {
  const blockers: string[] = [];
  const approvalStatus = row.approval_status as CampaignApprovalStatus;
  const quotaPerMinute = Number(row.quota_per_minute || 0);
  const usedInWindow = Number(row.used_in_window || 0);
  const monthlyRemaining = Number(row.monthly_quota || 0) > 0 ? Math.max(0, Number(row.monthly_quota) - Number(row.monthly_used || 0)) : Number.MAX_SAFE_INTEGER;
  const remaining = Math.max(0, Math.min(quotaPerMinute - usedInWindow, monthlyRemaining));
  if (approvalStatus !== 'APPROVED') blockers.push('Campaign approval is required');
  if (Boolean(row.system_kill_switch)) blockers.push('System kill switch is active');
  if (Boolean(row.oa_kill_switch)) blockers.push('OA kill switch is active');
  if (Boolean(row.campaign_kill_switch)) blockers.push('Campaign kill switch is active');
  if (!row.oa_id) blockers.push('A staging OA must be selected');
  if (row.oa_id && (!Boolean(row.oa_enabled) || row.oa_environment !== 'STAGING')) blockers.push('Selected OA is not an enabled staging OA');
  return {
    campaignId: String(row.campaign_id), approvalStatus,
    approvedBy: row.approved_by ? String(row.approved_by) : undefined,
    validatedAt: row.validated_at ? rowDate(row.validated_at) : undefined,
    approvedAt: row.approved_at ? rowDate(row.approved_at) : undefined,
    systemKillSwitch: Boolean(row.system_kill_switch), oaKillSwitch: Boolean(row.oa_kill_switch), campaignKillSwitch: Boolean(row.campaign_kill_switch),
    quota: { limitPerMinute: quotaPerMinute, usedInWindow, remaining },
    audience: { eligible: Number(row.eligible || 0), optedOut: Number(row.opted_out || 0), blocked: Number(row.blocked || 0) },
    canSchedule: blockers.length === 0,
    blockers
  };
}
const jobProjection = `j.id, j.workspace_id, j.campaign_revision_id, (select c.slug from campaigns c join campaign_revisions r on r.campaign_id=c.id where r.id=j.campaign_revision_id) as campaign_id, j.oa_integration_id as oa_id, j.scheduled_at, j.time_zone, j.available_at, j.mode, j.status, j.attempts, j.idempotency_key, j.last_error, j.created_at`;
const insertJobProjection = `id, workspace_id, campaign_revision_id, (select c.slug from campaigns c join campaign_revisions r on r.campaign_id=c.id where r.id=campaign_revision_id) as campaign_id, oa_integration_id as oa_id, scheduled_at, time_zone, available_at, mode, status, attempts, idempotency_key, last_error, created_at`;

export function createPostgresRepository(pool: Pool): Repository {
  const audit = async (actor: string, action: string, target: string, detail: string, workspaceId?: string) => { const workspace = workspaceId ? { rows: [{ id: workspaceId }] } : await pool.query<{ id: string }>('select id from workspaces order by created_at limit 1'); if (workspace.rows[0]) await pool.query('insert into audit_log (workspace_id, actor, action, target_type, target_id, detail) values ($1,$2,$3,$4,$5,$6::jsonb)', [workspace.rows[0].id, actor, action, 'api', target, JSON.stringify({ detail })]); };
  const transition = async (id: string, actor: string, status: string, action: string, where: string, workspaceId: string) => { const result = await pool.query(`update scheduler_jobs as j set status=$2, updated_at=now(), claimed_at=null, claimed_by=null where j.id=$1 and j.workspace_id=$3 and ${where} returning ${jobProjection}`, [id, status, workspaceId]); if (!result.rows[0]) throw new Error('job not found or transition is not allowed'); await audit(actor, action, id, `scheduler job transitioned to ${status}`, workspaceId); return mapJob(result.rows[0]); };
  return {
    kind: 'postgres' as const,
    async getUserByEmail(email) { const result = await pool.query('select u.id, u.workspace_id, u.email, u.display_name, u.role, u.password_hash, u.active from admin_users u join workspace_memberships m on m.admin_user_id=u.id and m.workspace_id=u.workspace_id and m.status=\'ACTIVE\' where lower(u.email)=lower($1) and u.active=true limit 2', [email]); return result.rows.length === 1 ? { id: String(result.rows[0].id), workspaceId: String(result.rows[0].workspace_id), email: String(result.rows[0].email), displayName: String(result.rows[0].display_name), role: result.rows[0].role as AdminRole, passwordHash: String(result.rows[0].password_hash), active: Boolean(result.rows[0].active), membershipStatus: 'ACTIVE' as const } : null; },
    async createSession(userId) { const token = createSessionToken(); const expiresAt = sessionExpiresAt(); await pool.query('insert into auth_sessions (user_id, token_hash, expires_at) values ($1,$2,$3)', [userId, hashSessionToken(token), expiresAt]); return { token, expiresAt }; },
    async getSessionUser(token) { const result = await pool.query('select u.id, u.workspace_id, u.email, u.display_name, u.role from auth_sessions s join admin_users u on u.id=s.user_id join workspace_memberships m on m.workspace_id=u.workspace_id and m.admin_user_id=u.id and m.status=\'ACTIVE\' where s.token_hash=$1 and s.revoked_at is null and s.expires_at>now() and u.active=true', [hashSessionToken(token)]); const row = result.rows[0]; return row ? { id: String(row.id), workspaceId: String(row.workspace_id), email: String(row.email), displayName: String(row.display_name), role: row.role as AdminRole } : null; },
    async revokeSession(token) { await pool.query('update auth_sessions set revoked_at=now() where token_hash=$1', [hashSessionToken(token)]); },
    async createAccountToken(input) {
      const client = await pool.connect();
      try {
        await client.query('begin');
        const account = await client.query('select id from admin_users where id=$1 and workspace_id=$2 and active=true', [input.adminUserId, input.workspaceId]);
        if (!account.rows[0]) throw new Error('account not found in this workspace');
        const issued = await issueAccountToken(client, { workspaceId: input.workspaceId, adminUserId: input.adminUserId, purpose: input.purpose, createdBy: input.actor, ttlMs: input.ttlMs });
        await client.query(
          "insert into audit_log(workspace_id,actor,action,target_type,target_id,detail) values ($1,$2,$3,'member',$4,$5::jsonb)",
          [input.workspaceId, input.actor, input.purpose === 'INVITE' ? 'ACCOUNT_INVITE_ISSUED' : 'ACCOUNT_RESET_ISSUED', input.adminUserId, JSON.stringify({ detail: `${input.purpose === 'INVITE' ? 'Invitation' : 'Password reset'} link issued; expires ${issued.expiresAt}` })]
        );
        await client.query('commit');
        return issued;
      } catch (error) { await client.query('rollback').catch(() => undefined); throw error; }
      finally { client.release(); }
    },
    async consumeAccountToken(token, password) {
      const client = await pool.connect();
      try {
        await client.query('begin');
        const result = await client.query<{ id: string; workspace_id: string; admin_user_id: string; purpose: AccountTokenPurpose; expires_at: Date; used_at: Date | null; email: string; display_name: string; role: AdminRole; active: boolean; membership_status: string }>(
          `select t.id,t.workspace_id,t.admin_user_id,t.purpose,t.expires_at,t.used_at,
                  u.email,u.display_name,u.role,u.active,m.status as membership_status
             from admin_account_tokens t
             join admin_users u on u.id=t.admin_user_id and u.workspace_id=t.workspace_id
             left join workspace_memberships m on m.workspace_id=t.workspace_id and m.admin_user_id=t.admin_user_id
            where t.token_hash=$1 for update of t`,
          [hashAccountToken(token)]
        );
        const invite = result.rows[0];
        if (!invite) throw new Error('account link is invalid or expired');
        const expired = Boolean(invite.used_at) || new Date(invite.expires_at).getTime() <= Date.now() || !invite.active;
        const purposeMismatch = (invite.purpose === 'INVITE' && invite.membership_status !== 'INVITED') || (invite.purpose === 'RESET' && invite.membership_status !== 'ACTIVE');
        if (expired || purposeMismatch) throw new Error('account link is invalid or expired');
        const passwordHash = await hashPassword(password);
        await client.query('update admin_users set password_hash=$1, active=true where id=$2 and workspace_id=$3', [passwordHash, invite.admin_user_id, invite.workspace_id]);
        await client.query("update workspace_memberships set status=case when status='INVITED' then 'ACTIVE' else status end where workspace_id=$1 and admin_user_id=$2", [invite.workspace_id, invite.admin_user_id]);
        await client.query('update admin_account_tokens set used_at=now() where id=$1', [invite.id]);
        await client.query('update auth_sessions set revoked_at=now() where user_id=$1 and revoked_at is null', [invite.admin_user_id]);
        await client.query(
          "insert into audit_log(workspace_id,actor,action,target_type,target_id,detail) values ($1,$2,$3,'member',$4,$5::jsonb)",
          [invite.workspace_id, invite.email, invite.purpose === 'INVITE' ? 'MEMBER_INVITE_ACCEPTED' : 'PASSWORD_RESET_COMPLETED', invite.admin_user_id, JSON.stringify({ detail: invite.purpose === 'INVITE' ? 'Invitation accepted and membership activated' : 'Password reset completed; existing sessions revoked' })]
        );
        await client.query('commit');
        return { id: String(invite.admin_user_id), workspaceId: String(invite.workspace_id), email: String(invite.email), displayName: String(invite.display_name), role: invite.role };
      } catch (error) { await client.query('rollback').catch(() => undefined); throw error; }
      finally { client.release(); }
    },
    async listCampaigns(workspaceId) { const result = await pool.query(`select c.slug as id, c.name, c.title, c.description, c.image, c.cta, c.flex_file, c.active, r.revision, r.flex_json from campaigns c left join lateral (select revision, flex_json from campaign_revisions where campaign_id=c.id order by revision desc limit 1) r on true where c.active and ($1::uuid is null or c.workspace_id=$1) order by c.created_at`, [workspaceId || null]); return result.rows.map((row) => { const campaign = { id: String(row.id), name: String(row.name), title: String(row.title), description: String(row.description), image: String(row.image), cta: String(row.cta), flexFile: String(row.flex_file), active: Boolean(row.active) }; return { ...campaign, latestRevision: row.revision ? Number(row.revision) : undefined, flexJson: (row.flex_json as Record<string, unknown> | undefined) ?? bundledTemplate(campaign) }; }); },
    async listOas(workspaceId) { const result = await pool.query(`select oa.id, oa.display_name, oa.basic_id, oa.provider_id, oa.environment, oa.enabled, exists(select 1 from oa_credential_vault v where v.oa_integration_id=oa.id and v.workspace_id=oa.workspace_id) as secret_configured, oa.connection_status, oa.credential_status, oa.quota_per_minute, oa.kill_switch, oa.kill_switch_reason from oa_integrations oa where ($1::uuid is null or oa.workspace_id=$1) order by oa.created_at`, [workspaceId || null]); return result.rows.map(mapOa); },
    async listCustomers(workspaceId) { const result = await pool.query('select id, provider_id, line_user_key, display_name, opt_in, blocked_at from customers where ($1::uuid is null or workspace_id=$1) order by created_at desc limit 500', [workspaceId || null]); return result.rows.map((row) => ({ id: String(row.id), providerId: String(row.provider_id), lineUserKey: String(row.line_user_key), displayName: row.display_name ? String(row.display_name) : undefined, optIn: Boolean(row.opt_in), blockedAt: row.blocked_at ? rowDate(row.blocked_at) : undefined })); },
    async listJobs(workspaceId) { const result = await pool.query(`select ${jobProjection} from scheduler_jobs j where ($1::uuid is null or j.workspace_id=$1) order by j.scheduled_at`, [workspaceId || null]); return result.rows.map(mapJob); },
    async listOutbox(workspaceId, jobId) { const result = await pool.query('select id, workspace_id, scheduler_job_id, oa_integration_id, recipient_key, idempotency_key, line_retry_key, status, attempts, provider_status, provider_request_id, last_error, created_at, updated_at from outbox_deliveries where ($1::uuid is null or workspace_id=$1) and ($2::uuid is null or scheduler_job_id=$2) order by created_at desc', [workspaceId || null, jobId || null]); return result.rows.map(mapOutbox); },
    async listAudit(workspaceId) { const result = await pool.query('select id, action, actor, target_id as target, coalesce(detail->>\'detail\', \'\') as detail, created_at from audit_log where ($1::uuid is null or workspace_id=$1) order by created_at desc limit 100', [workspaceId || null]); return result.rows.map((row) => ({ id: String(row.id), action: String(row.action), actor: String(row.actor), target: String(row.target), detail: String(row.detail), createdAt: rowDate(row.created_at) })); },
    async dashboard(workspaceId) { const countsResult = await pool.query('select status, count(*)::int as count from scheduler_jobs where ($1::uuid is null or workspace_id=$1) group by status', [workspaceId || null]); const counts: Record<string, number> = {}; for (const row of countsResult.rows) counts[normalizeStatus(String(row.status))] = Number(row.count); const jobs = await this.listJobs(workspaceId); return { mode: 'DRY_RUN' as const, counts, nextJob: jobs.find((job) => job.status === 'SCHEDULED' || job.status === 'RETRYABLE') || null }; },
    async addJob(input) { const campaign = await pool.query<{ id: string }>('select c.id from campaigns c where c.workspace_id=$1 and c.slug=$2 and c.active', [input.workspaceId, input.campaignId]); const oa = await pool.query<{ id: string }>('select id from oa_integrations where workspace_id=$1 and id=$2 and enabled and environment=\'STAGING\'', [input.workspaceId, input.oaId]); if (!campaign.rows[0]) throw new Error('campaignId is not an active staging campaign'); if (!oa.rows[0]) throw new Error('oaId is not an enabled staging OA in this workspace'); if (input.status === 'SCHEDULED') { const readiness = await this.getCampaignReadiness(input.campaignId, input.workspaceId, input.oaId); if (!readiness.canSchedule) throw new Error(`campaign is not ready: ${readiness.blockers.join(', ')}`); } const revision = await pool.query<{ id: string }>('select id from campaign_revisions where campaign_id=$1 order by revision desc limit 1', [campaign.rows[0].id]); if (!revision.rows[0]) throw new Error('campaign has no Flex revision'); const parsed = new Date(input.scheduledAt); if (Number.isNaN(parsed.valueOf())) throw new Error('scheduledAt must be a valid ISO date'); const clientRequestKey = input.clientRequestKey || null; if (clientRequestKey) { const existing = await pool.query(`select ${jobProjection} from scheduler_jobs j where j.workspace_id=$1 and j.client_request_key=$2`, [input.workspaceId, clientRequestKey]); if (existing.rows[0]) return mapJob(existing.rows[0]); } const result = await pool.query(`insert into scheduler_jobs (workspace_id, campaign_revision_id, oa_integration_id, mode, status, scheduled_at, available_at, time_zone, idempotency_key, client_request_key) values ($1,$2,$3,$8,$4,$5,$5,$6,gen_random_uuid(),$7) on conflict (workspace_id, client_request_key) do nothing returning ${insertJobProjection}`, [input.workspaceId, revision.rows[0].id, oa.rows[0].id, input.status, parsed.toISOString(), input.timeZone, clientRequestKey, input.mode || 'DRY_RUN']); if (!result.rows[0]) { if (!clientRequestKey) throw new Error('could not create scheduler job'); const existing = await pool.query(`select ${jobProjection} from scheduler_jobs j where j.workspace_id=$1 and j.client_request_key=$2`, [input.workspaceId, clientRequestKey]); if (!existing.rows[0]) throw new Error('could not resolve scheduler job for the client request key'); return mapJob(existing.rows[0]); } await audit(input.actor, input.status === 'DRAFT' ? 'SCHEDULE_DRAFT_CREATED' : 'SCHEDULE_CREATED', String(result.rows[0].id), `${input.mode || 'DRY_RUN'} ${input.status.toLowerCase()} created for ${input.timeZone}`, input.workspaceId); return mapJob(result.rows[0]); },
    async scheduleJob(id, actor, workspaceId) { return transition(id, actor, 'SCHEDULED', 'SCHEDULE_SCHEDULED', `j.status='DRAFT'`, workspaceId); },
    async pauseJob(id, actor, workspaceId) { return transition(id, actor, 'PAUSED', 'SCHEDULE_PAUSED', `j.status in ('DRAFT','SCHEDULED','RETRYABLE','QUEUED')`, workspaceId); },
    async resumeJob(id, actor, workspaceId) { const result = await pool.query(`update scheduler_jobs as j set status='SCHEDULED', available_at=greatest(j.scheduled_at,now()), updated_at=now(), claimed_at=null, claimed_by=null where j.id=$1 and j.workspace_id=$2 and j.status='PAUSED' returning ${jobProjection}`, [id, workspaceId]); if (!result.rows[0]) throw new Error('only paused jobs can be resumed'); await audit(actor, 'SCHEDULE_RESUMED', id, 'scheduler job resumed', workspaceId); return mapJob(result.rows[0]); },
    async cancelJob(id, actor, workspaceId) { return transition(id, actor, 'CANCELLED', 'SCHEDULE_CANCELLED', `j.status in ('DRAFT','SCHEDULED','PAUSED','RETRYABLE','QUEUED')`, workspaceId); },
    async retryJob(id, actor, workspaceId) { return transition(id, actor, 'RETRYABLE', 'SCHEDULE_RETRY', `j.status in ('PAUSED','FAILED','FAILED_FINAL','RETRYABLE')`, workspaceId); },
    async runDryRun(id, actor, workspaceId) { const result = await pool.query(`update scheduler_jobs as j set status='SCHEDULED', scheduled_at=now(), available_at=now(), claimed_at=null, claimed_by=null, updated_at=now() where j.id=$1 and j.workspace_id=$2 and j.mode='DRY_RUN' and j.status in ('DRAFT','SCHEDULED','RETRYABLE','FAILED') returning ${jobProjection}`, [id, workspaceId]); if (!result.rows[0]) throw new Error('job is missing, paused, cancelled, completed, or not a DRY_RUN job'); await audit(actor, 'DRY_RUN_ENQUEUED', id, 'dry-run queued through the outbox worker pipeline', workspaceId); return mapJob(result.rows[0]); },
    async claimDueJob(workerId, now = new Date(), jobId) { const result = await pool.query(`with next_job as (select id from scheduler_jobs where status in ('SCHEDULED','RETRYABLE','QUEUED') and available_at <= $2 and scheduled_at <= $2 and ($3::uuid is null or id=$3) order by available_at, created_at for update skip locked limit 1) update scheduler_jobs j set status='CLAIMED', claimed_at=now(), claimed_by=$1, attempts=j.attempts+1, updated_at=now() from next_job where j.id=next_job.id returning ${jobProjection}`, [workerId, now.toISOString(), jobId || null]); if (!result.rows[0]) return null; const job = mapJob(result.rows[0]); await audit(workerId, 'WORKER_CLAIMED', job.id, `worker claimed ${job.id}`, String(result.rows[0].workspace_id)); return job; },
    async markJobSending(id, workerId) { const result = await pool.query(`update scheduler_jobs as j set status='SENDING', updated_at=now() where j.id=$1 and j.status='CLAIMED' and j.claimed_by=$2 returning ${jobProjection}`, [id, workerId]); if (!result.rows[0]) throw new Error('job claim is no longer owned by this worker'); return mapJob(result.rows[0]); },
    async markJobCompleted(id, workerId) { const result = await pool.query(`update scheduler_jobs as j set status='COMPLETED', last_error=null, claimed_at=null, claimed_by=null, updated_at=now() where j.id=$1 and j.status in ('CLAIMED','SENDING') and j.claimed_by=$2 returning ${jobProjection}`, [id, workerId]); if (!result.rows[0]) throw new Error('job completion is no longer owned by this worker'); await audit(workerId, 'WORKER_COMPLETED', id, 'worker completed the outbox delivery pipeline', String(result.rows[0].workspace_id)); return mapJob(result.rows[0]); },
    async markJobFailure(id, workerId, error, retryAt) { const status = retryAt ? 'RETRYABLE' : 'FAILED'; const result = await pool.query(`update scheduler_jobs as j set status=$3, available_at=coalesce($4, j.available_at), last_error=$5, claimed_at=null, claimed_by=null, updated_at=now() where j.id=$1 and j.status in ('CLAIMED','SENDING') and j.claimed_by=$2 returning ${jobProjection}`, [id, workerId, status, retryAt, error.slice(0, 500)]); if (!result.rows[0]) throw new Error('job failure is no longer owned by this worker'); await audit(workerId, retryAt ? 'WORKER_RETRY' : 'WORKER_FAILED', id, retryAt ? `retry scheduled at ${retryAt.toISOString()}` : 'max attempts reached', String(result.rows[0].workspace_id)); return mapJob(result.rows[0]); },
    async prepareOutbox(jobId, workerId) {
      const client = await pool.connect();
      try {
        await client.query('begin');
        const job = await client.query<{ id: string; workspace_id: string; oa_integration_id: string }>("select id, workspace_id, oa_integration_id from scheduler_jobs where id=$1 and status='SENDING' and claimed_by=$2 for update", [jobId, workerId]);
        if (!job.rows[0]) throw new Error('scheduler job is no longer owned by this worker');
        await client.query(`with eligible as (select j.workspace_id, j.id as scheduler_job_id, j.oa_integration_id, c.line_user_key as recipient_key from scheduler_jobs j join oa_integrations oa on oa.id=j.oa_integration_id join customers c on c.workspace_id=j.workspace_id and c.provider_id=oa.provider_id where j.id=$1 and c.opt_in=true and c.blocked_at is null), rows_with_keys as (select e.*, gen_random_uuid() as delivery_key from eligible e), inserted_recipients as (insert into outbox_deliveries(workspace_id,scheduler_job_id,oa_integration_id,recipient_key,idempotency_key,line_retry_key) select workspace_id,scheduler_job_id,oa_integration_id,recipient_key,delivery_key,delivery_key from rows_with_keys on conflict (scheduler_job_id,recipient_key) do nothing), inserted_fallback as (insert into outbox_deliveries(workspace_id,scheduler_job_id,oa_integration_id,recipient_key,idempotency_key,line_retry_key) select j.workspace_id,j.id,j.oa_integration_id,'__campaign__',gen_random_uuid(),gen_random_uuid() from scheduler_jobs j where j.id=$1 and not exists (select 1 from eligible)) select 1`, [jobId]);
        const deliveries = await client.query('select id, workspace_id, scheduler_job_id, oa_integration_id, recipient_key, idempotency_key, line_retry_key, status, attempts, provider_status, provider_request_id, last_error, created_at, updated_at from outbox_deliveries where workspace_id=$1 and scheduler_job_id=$2 order by created_at', [job.rows[0].workspace_id, jobId]);
        await client.query('commit');
        return deliveries.rows.map(mapOutbox);
      } catch (error) {
        await client.query('rollback');
        throw error;
      } finally { client.release(); }
    },
    async getDeliveryContext(deliveryId, workspaceId) {
      const result = await pool.query('select d.id as delivery_id, d.workspace_id, d.scheduler_job_id, d.oa_integration_id, d.recipient_key, j.campaign_revision_id, r.flex_json from outbox_deliveries d join scheduler_jobs j on j.id=d.scheduler_job_id and j.workspace_id=d.workspace_id join campaign_revisions r on r.id=j.campaign_revision_id where d.id=$1 and d.workspace_id=$2', [deliveryId, workspaceId]);
      const row = result.rows[0];
      if (!row) throw new Error('outbox delivery not found in this workspace');
      return { jobId: String(row.scheduler_job_id), workspaceId: String(row.workspace_id), oaId: String(row.oa_integration_id), campaignRevisionId: String(row.campaign_revision_id), recipientKey: String(row.recipient_key), flexJson: row.flex_json as Record<string, unknown> };
    },
    async reserveDeliverySlot(input) {
      const now = input.now || new Date();
      const windowStartedAt = new Date(Math.floor(now.getTime() / 60_000) * 60_000).toISOString();
      const client = await pool.connect();
      try {
        await client.query('begin');
        const oa = await client.query<{ quota_per_minute: number; monthly_quota: number; monthly_used: number }>("select quota_per_minute, monthly_quota, monthly_used from oa_integrations where id=$1 and workspace_id=$2 and environment='STAGING' and enabled for update", [input.oaId, input.workspaceId]);
        if (!oa.rows[0]) throw new OaPolicyError('OA_NOT_AVAILABLE', 'selected staging OA is not available');
        const window = await client.query<{ used_count: number }>('select used_count from oa_rate_limit_windows where oa_integration_id=$1 and window_started_at=$2', [input.oaId, windowStartedAt]);
        if (Number(window.rows[0]?.used_count || 0) >= Number(oa.rows[0].quota_per_minute)) throw new OaPolicyError('RATE_LIMITED', 'OA per-minute delivery limit reached', true);
        if (Number(oa.rows[0].monthly_quota) > 0 && Number(oa.rows[0].monthly_used) >= Number(oa.rows[0].monthly_quota)) throw new OaPolicyError('QUOTA_EXCEEDED', 'OA monthly quota is exhausted');
        if (input.count) {
          await client.query('insert into oa_rate_limit_windows (oa_integration_id, window_started_at, used_count) values ($1,$2,1) on conflict (oa_integration_id, window_started_at) do update set used_count=oa_rate_limit_windows.used_count+1', [input.oaId, windowStartedAt]);
          await client.query('update oa_integrations set monthly_used=monthly_used+1 where id=$1 and workspace_id=$2', [input.oaId, input.workspaceId]);
        }
        await client.query('commit');
        return { windowStartedAt: input.count ? windowStartedAt : null, counted: input.count };
      } catch (error) {
        await client.query('rollback').catch(() => undefined);
        throw error;
      } finally { client.release(); }
    },
    async releaseDeliverySlot(input) {
      if (!input.windowStartedAt) return;
      const client = await pool.connect();
      try {
        await client.query('begin');
        await client.query('update oa_rate_limit_windows set used_count=greatest(used_count-1,0) where oa_integration_id=$1 and window_started_at=$2', [input.oaId, input.windowStartedAt]);
        await client.query('update oa_integrations set monthly_used=greatest(monthly_used-1,0) where id=$1 and workspace_id=$2', [input.oaId, input.workspaceId]);
        await client.query('commit');
      } catch (error) {
        await client.query('rollback').catch(() => undefined);
        throw error;
      } finally { client.release(); }
    },
    async reconcileOutboxDelivery(input) {
      const lastError = input.status === 'SENT' ? null : 'operator marked failed after UNKNOWN';
      const result = await pool.query("update outbox_deliveries set status=$4, last_error=$5, claimed_by=null, claimed_at=null, updated_at=now() where id=$1 and scheduler_job_id=$2 and workspace_id=$3 and status='UNKNOWN' returning id, workspace_id, scheduler_job_id, oa_integration_id, recipient_key, idempotency_key, line_retry_key, status, attempts, provider_status, provider_request_id, last_error, created_at, updated_at", [input.deliveryId, input.jobId, input.workspaceId, input.status, lastError]);
      if (!result.rows[0]) throw new Error('only UNKNOWN deliveries can be reconciled');
      await audit(input.actor, 'OUTBOX_RECONCILED', input.deliveryId, `operator reconciled UNKNOWN delivery as ${input.status}`, input.workspaceId);
      return mapOutbox(result.rows[0]);
    },
    async markOutboxSending(id, workerId) { const result = await pool.query('update outbox_deliveries d set status=\'SENDING\', attempts=d.attempts+1, claimed_by=$2, claimed_at=now(), updated_at=now() where d.id=$1 and d.status in (\'PENDING\',\'RETRYABLE\') and exists (select 1 from scheduler_jobs j where j.id=d.scheduler_job_id and j.workspace_id=d.workspace_id and j.status in (\'CLAIMED\',\'SENDING\') and j.claimed_by=$2) returning id, workspace_id, scheduler_job_id, oa_integration_id, recipient_key, idempotency_key, line_retry_key, status, attempts, provider_status, provider_request_id, last_error, created_at, updated_at', [id, workerId]); if (!result.rows[0]) throw new Error('outbox delivery is no longer owned by this worker'); return mapOutbox(result.rows[0]); },
    async markOutboxCompleted(id, workerId, resultInput) { const result = await pool.query('update outbox_deliveries d set status=\'SENT\', provider_status=$3, provider_request_id=$4, last_error=null, claimed_by=null, claimed_at=null, updated_at=now() where d.id=$1 and d.claimed_by=$2 and d.status=\'SENDING\' and exists (select 1 from scheduler_jobs j where j.id=d.scheduler_job_id and j.workspace_id=d.workspace_id and j.status=\'SENDING\' and j.claimed_by=$2) returning d.id, d.workspace_id, d.scheduler_job_id, d.oa_integration_id, d.recipient_key, d.idempotency_key, d.line_retry_key, d.status, d.attempts, d.provider_status, d.provider_request_id, d.last_error, d.created_at, d.updated_at', [id, workerId, resultInput.providerStatus || null, resultInput.providerRequestId || null]); if (!result.rows[0]) throw new Error('outbox completion is no longer owned by this worker'); return mapOutbox(result.rows[0]); },
    async markOutboxFailure(id, workerId, error, status, resultInput = {}) { const result = await pool.query('update outbox_deliveries d set status=$3, provider_status=$4, provider_request_id=$5, last_error=$6, claimed_by=null, claimed_at=null, updated_at=now() where d.id=$1 and d.claimed_by=$2 and d.status=\'SENDING\' and exists (select 1 from scheduler_jobs j where j.id=d.scheduler_job_id and j.workspace_id=d.workspace_id and j.status=\'SENDING\' and j.claimed_by=$2) returning d.id, d.workspace_id, d.scheduler_job_id, d.oa_integration_id, d.recipient_key, d.idempotency_key, d.line_retry_key, d.status, d.attempts, d.provider_status, d.provider_request_id, d.last_error, d.created_at, d.updated_at', [id, workerId, status, resultInput.providerStatus || null, resultInput.providerRequestId || null, error.slice(0, 500)]); if (!result.rows[0]) throw new Error('outbox failure is no longer owned by this worker'); return mapOutbox(result.rows[0]); },
    async recoverStaleJobs(staleBefore, now = new Date()) { const client = await pool.connect(); try { await client.query('begin'); const result = await client.query(`update scheduler_jobs as j set status='RETRYABLE', available_at=$2, claimed_at=null, claimed_by=null, last_error='worker lease recovered after restart', updated_at=$2 where status in ('CLAIMED','SENDING') and claimed_at < $1 returning j.id, j.workspace_id`, [staleBefore.toISOString(), now.toISOString()]); for (const row of result.rows) await client.query("update outbox_deliveries set status='RETRYABLE', claimed_by=null, claimed_at=null, last_error='outbox lease recovered after worker restart', updated_at=$2 where scheduler_job_id=$1 and workspace_id=$3 and status='SENDING'", [row.id, now.toISOString(), row.workspace_id]); await client.query('commit'); for (const row of result.rows) await audit('worker-recovery', 'WORKER_RECOVERED', String(row.id), 'stale worker lease recovered', String(row.workspace_id)); return result.rowCount || 0; } catch (error) { await client.query('rollback'); throw error; } finally { client.release(); } },
    async listRevisions(campaignId, workspaceId) { const result = await pool.query('select r.id, c.slug as campaign_id, r.revision, r.flex_json, r.state, r.created_by, r.created_at from campaign_revisions r join campaigns c on c.id=r.campaign_id where c.slug=$1 and ($2::uuid is null or c.workspace_id=$2) order by r.revision desc', [campaignId, workspaceId || null]); return result.rows.map((row) => ({ id: String(row.id), campaignId: String(row.campaign_id), revision: Number(row.revision), flexJson: row.flex_json as Record<string, unknown>, state: String(row.state), createdBy: String(row.created_by), createdAt: rowDate(row.created_at) })); },
    async createRevision(campaignId, flexJson, actor, workspaceId) { const result = await pool.query('insert into campaign_revisions (campaign_id, revision, flex_json, state, created_by) select c.id, coalesce((select max(revision)+1 from campaign_revisions where campaign_id=c.id),1), $2::jsonb, \'DRAFT\', $3 from campaigns c where c.slug=$1 and ($4::uuid is null or c.workspace_id=$4) returning id, (select slug from campaigns where id=campaign_id) as campaign_id, revision, flex_json, state, created_by, created_at', [campaignId, JSON.stringify(flexJson), actor, workspaceId || null]); if (!result.rows[0]) throw new Error('campaign not found'); const campaignWorkspace = await pool.query<{ workspace_id: string }>('select c.workspace_id from campaigns c join campaign_revisions r on r.campaign_id=c.id where r.id=$1', [result.rows[0].id]); await audit(actor, 'FLEX_REVISION_CREATED', campaignId, `revision ${result.rows[0].revision}`, campaignWorkspace.rows[0]?.workspace_id); const row = result.rows[0]; return { id: String(row.id), campaignId: String(row.campaign_id), revision: Number(row.revision), flexJson: row.flex_json as Record<string, unknown>, state: String(row.state), createdBy: String(row.created_by), createdAt: rowDate(row.created_at) }; },
    async acceptWebhook(input) { const client = await pool.connect(); try { await client.query('begin'); const oa = await client.query<{ id: string; workspace_id: string; provider_id: string }>('select id, workspace_id, provider_id from oa_integrations where id=$1 and environment=\'STAGING\'', [input.oaId]); if (!oa.rows[0]) throw new Error('staging OA not found'); const result = await client.query('insert into webhook_events (workspace_id, oa_integration_id, webhook_event_id, payload_hash) values ($1,$2,$3,$4) on conflict (oa_integration_id, webhook_event_id) do nothing returning id', [oa.rows[0].workspace_id, input.oaId, input.eventId, input.payloadHash]); const duplicate = result.rowCount === 0; if (!duplicate && input.lineUserKey && input.eventType === 'follow') await client.query('insert into customers (workspace_id, provider_id, line_user_key, opt_in) values ($1,$2,$3,true) on conflict (workspace_id, provider_id, line_user_key) do update set opt_in=true, blocked_at=null', [oa.rows[0].workspace_id, oa.rows[0].provider_id, input.lineUserKey]); if (!duplicate && input.lineUserKey && input.eventType === 'unfollow') await client.query('insert into customers (workspace_id, provider_id, line_user_key, opt_in, blocked_at) values ($1,$2,$3,false,now()) on conflict (workspace_id, provider_id, line_user_key) do update set opt_in=false, blocked_at=now()', [oa.rows[0].workspace_id, oa.rows[0].provider_id, input.lineUserKey]); await client.query('commit'); return { accepted: true, duplicate }; } catch (error) { await client.query('rollback'); throw error; } finally { client.release(); } },
    async createOa(input) { const result = await pool.query('insert into oa_integrations(workspace_id,provider_id,basic_id,display_name,environment,enabled,connection_status,credential_status) values ($1,$2,$3,$4,\'STAGING\',false,\'NOT_CONFIGURED\',\'NOT_CONFIGURED\') returning id, display_name, basic_id, provider_id, environment, enabled, false as secret_configured, connection_status, credential_status, quota_per_minute, kill_switch, kill_switch_reason', [input.workspaceId, input.providerId, input.basicId, input.displayName]); await audit(input.actor, 'OA_CONNECTION_CREATED', String(result.rows[0].id), 'Staging OA metadata created without credentials', input.workspaceId); return mapOa(result.rows[0]); },
    async validateOa(id, workspaceId, actor) { const result = await pool.query('update oa_integrations oa set connection_status=\'DRY_RUN_READY\', credential_status=case when exists(select 1 from oa_credential_vault v where v.oa_integration_id=oa.id and v.workspace_id=oa.workspace_id) then \'REFERENCE_CONFIGURED\' else \'NOT_CONFIGURED\' end, validation_error=null, last_validated_at=now() where oa.id=$1 and oa.workspace_id=$2 and oa.environment=\'STAGING\' returning oa.id, oa.display_name, oa.basic_id, oa.provider_id, oa.environment, oa.enabled, exists(select 1 from oa_credential_vault v where v.oa_integration_id=oa.id and v.workspace_id=oa.workspace_id) as secret_configured, oa.connection_status, oa.credential_status, oa.quota_per_minute, oa.kill_switch, oa.kill_switch_reason', [id, workspaceId]); if (!result.rows[0]) throw new Error('staging OA not found in this workspace'); await audit(actor, 'OA_CREDENTIAL_REFERENCE_VALIDATED', id, 'Only server-side secret reference metadata was checked; no provider call was made', workspaceId); return mapOa(result.rows[0]); },
    async setOaKillSwitch(id, workspaceId, enabled, reason, actor) { const result = await pool.query('update oa_integrations oa set kill_switch=$3, kill_switch_reason=$4 where oa.id=$1 and oa.workspace_id=$2 and oa.environment=\'STAGING\' returning oa.id, oa.display_name, oa.basic_id, oa.provider_id, oa.environment, oa.enabled, exists(select 1 from oa_credential_vault v where v.oa_integration_id=oa.id and v.workspace_id=oa.workspace_id) as secret_configured, oa.connection_status, oa.credential_status, oa.quota_per_minute, oa.kill_switch, oa.kill_switch_reason', [id, workspaceId, enabled, reason.slice(0, 240)]); if (!result.rows[0]) throw new Error('staging OA not found in this workspace'); await audit(actor, enabled ? 'OA_KILL_SWITCH_ON' : 'OA_KILL_SWITCH_OFF', id, reason, workspaceId); return mapOa(result.rows[0]); },
    async setOaEnabled(id, workspaceId, enabled, actor) { const result = await pool.query('update oa_integrations oa set enabled=$3 where oa.id=$1 and oa.workspace_id=$2 and oa.environment=\'STAGING\' returning oa.id, oa.display_name, oa.basic_id, oa.provider_id, oa.environment, oa.enabled, exists(select 1 from oa_credential_vault v where v.oa_integration_id=oa.id and v.workspace_id=oa.workspace_id) as secret_configured, oa.connection_status, oa.credential_status, oa.quota_per_minute, oa.kill_switch, oa.kill_switch_reason', [id, workspaceId, enabled]); if (!result.rows[0]) throw new Error('staging OA not found in this workspace'); await audit(actor, enabled ? 'OA_ENABLED' : 'OA_DISABLED', id, 'Staging OA enabled state changed', workspaceId); return mapOa(result.rows[0]); },
    async setSystemKillSwitch(workspaceId, enabled, reason, actor) { await pool.query('insert into workspace_controls(workspace_id,system_kill_switch,reason,updated_by,updated_at) values ($1,$2,$3,$4,now()) on conflict (workspace_id) do update set system_kill_switch=excluded.system_kill_switch, reason=excluded.reason, updated_by=excluded.updated_by, updated_at=now()', [workspaceId, enabled, reason.slice(0, 240), actor]); await audit(actor, enabled ? 'SYSTEM_KILL_SWITCH_ON' : 'SYSTEM_KILL_SWITCH_OFF', workspaceId, reason, workspaceId); return { enabled, reason }; },
    async setCampaignKillSwitch(campaignId, workspaceId, enabled, reason, actor) { const campaign = await pool.query<{ id: string }>('select id from campaigns where slug=$1 and workspace_id=$2', [campaignId, workspaceId]); if (!campaign.rows[0]) throw new Error('campaign not found'); await pool.query('insert into campaign_controls(workspace_id,campaign_id,campaign_kill_switch,reason,updated_at) values ($1,$2,$3,$4,now()) on conflict (campaign_id) do update set campaign_kill_switch=excluded.campaign_kill_switch, reason=excluded.reason, updated_at=now()', [workspaceId, campaign.rows[0].id, enabled, reason.slice(0, 240)]); await audit(actor, enabled ? 'CAMPAIGN_KILL_SWITCH_ON' : 'CAMPAIGN_KILL_SWITCH_OFF', campaignId, reason, workspaceId); return this.getCampaignReadiness(campaignId, workspaceId); },
    async validateCampaign(campaignId, workspaceId, actor) { const result = await pool.query('update campaign_controls cc set approval_status=\'VALIDATED\', validated_at=now(), validated_by=$3, updated_at=now() from campaigns c where cc.campaign_id=c.id and c.slug=$1 and cc.workspace_id=$2 returning c.slug', [campaignId, workspaceId, actor]); if (!result.rows[0]) throw new Error('campaign control not found'); await audit(actor, 'CAMPAIGN_VALIDATED', campaignId, 'Preview and validation completed', workspaceId); return this.getCampaignReadiness(campaignId, workspaceId); },
    async approveCampaign(campaignId, workspaceId, actor) { const result = await pool.query('update campaign_controls cc set approval_status=\'APPROVED\', approved_at=now(), approved_by=$3, updated_at=now() from campaigns c where cc.campaign_id=c.id and c.slug=$1 and cc.workspace_id=$2 and cc.approval_status=\'VALIDATED\' returning c.slug', [campaignId, workspaceId, actor]); if (!result.rows[0]) throw new Error('campaign must be validated before approval'); await audit(actor, 'CAMPAIGN_APPROVED', campaignId, 'Campaign approved for Staging DRY_RUN scheduling', workspaceId); return this.getCampaignReadiness(campaignId, workspaceId); },
    async getCampaignReadiness(campaignId, workspaceId, oaId) { const result = await pool.query(`select c.slug as campaign_id, co.approval_status, co.validated_at, co.approved_at, co.approved_by, co.campaign_kill_switch, wc.system_kill_switch, oa.id as oa_id, oa.enabled as oa_enabled, oa.environment as oa_environment, oa.kill_switch as oa_kill_switch, oa.quota_per_minute, oa.monthly_quota, oa.monthly_used, coalesce(rl.used_count,0) as used_in_window, count(*) filter (where cu.opt_in=true and cu.blocked_at is null)::int as eligible, count(*) filter (where cu.opt_in=false)::int as opted_out, count(*) filter (where cu.blocked_at is not null)::int as blocked from campaigns c join campaign_controls co on co.campaign_id=c.id and co.workspace_id=c.workspace_id left join workspace_controls wc on wc.workspace_id=c.workspace_id left join oa_integrations oa on oa.workspace_id=c.workspace_id and (($3::uuid is null and oa.enabled=true) or oa.id=$3::uuid) left join oa_rate_limit_windows rl on rl.oa_integration_id=oa.id and rl.window_started_at=date_trunc('minute',now()) left join customers cu on cu.workspace_id=c.workspace_id and cu.provider_id=oa.provider_id where c.slug=$1 and c.workspace_id=$2 group by c.slug,co.approval_status,co.validated_at,co.approved_at,co.approved_by,co.campaign_kill_switch,wc.system_kill_switch,oa.id,oa.enabled,oa.environment,oa.kill_switch,oa.quota_per_minute,oa.monthly_quota,oa.monthly_used,rl.used_count`, [campaignId, workspaceId, oaId || null]); if (!result.rows[0]) throw new Error('campaign readiness not found'); return mapReadiness(result.rows[0]); },
  };
}

export function createMemoryRepository(): Repository {
  if ((process.env.PERSISTENCE || '').trim().toLowerCase() !== 'memory') throw new Error('Memory repository requires explicit PERSISTENCE=memory; it is never a Postgres fallback');
  if ((process.env.APP_MODE || '').trim().toUpperCase() !== 'DRY_RUN') throw new Error('PERSISTENCE=memory requires explicit APP_MODE=DRY_RUN');
  if ((process.env.LINE_LIVE_ENABLED || '').trim().toLowerCase() === 'true') throw new Error('PERSISTENCE=memory cannot run with LINE_LIVE_ENABLED=true');
  const memoryPassword = process.env.MEMORY_ADMIN_PASSWORD;
  if (!memoryPassword || memoryPassword.length < 12) throw new Error('PERSISTENCE=memory requires MEMORY_ADMIN_PASSWORD with at least 12 characters; no fallback credential exists');
  const campaigns = readSeed(); const oas: OaIntegration[] = [{ id: 'oa-staging-primary', displayName: 'LINE OA หลัก (Staging)', basicId: '@453yfyvc', providerId: 'staging-provider', environment: 'STAGING', enabled: true, secretConfigured: false, connectionStatus: 'DRY_RUN_READY', credentialStatus: 'NOT_CONFIGURED', quotaPerMinute: 60, killSwitch: false }, { id: 'oa-staging-mock', displayName: 'LINE OA สำรอง (Mock)', basicId: '@mock-campaign', providerId: 'mock-provider', environment: 'STAGING', enabled: false, secretConfigured: false, connectionStatus: 'NOT_CONFIGURED', credentialStatus: 'NOT_CONFIGURED', quotaPerMinute: 60, killSwitch: false }]; const customers: Customer[] = []; const jobs: SchedulerJob[] = []; const deliveries: OutboxDelivery[] = []; const audit: AuditEvent[] = []; const users: StoredUser[] = [{ id: 'memory-admin', workspaceId: 'memory-workspace', email: process.env.MEMORY_ADMIN_EMAIL || 'admin@memory.local', displayName: 'Memory Admin', role: 'owner', passwordHash: hashPasswordSync(memoryPassword), active: true, membershipStatus: 'ACTIVE' }]; const sessions = new Map<string, { userId: string; expiresAt: Date }>(); const accountTokens = new Map<string, { id: string; workspaceId: string; adminUserId: string; purpose: AccountTokenPurpose; expiresAt: Date; usedAt?: Date }>(); const jobClientKeys = new Map<string, string>(); const revisions = new Map<string, CampaignRevision[]>(); const webhookEvents = new Set<string>(); const rateWindows = new Map<string, { windowStartedAt: string; used: number }>(); const campaignControls = new Map<string, { approvalStatus: CampaignApprovalStatus; killSwitch: boolean }>(campaigns.map((campaign) => [campaign.id, { approvalStatus: 'APPROVED', killSwitch: false }])); let systemKillSwitch = false;
  for (const campaign of campaigns) revisions.set(campaign.id, [{ id: `revision-${campaign.id}-1`, campaignId: campaign.id, revision: 1, flexJson: campaign.flexJson!, state: 'PUBLISHED', createdBy: 'seed', createdAt: new Date().toISOString() }]);
  const addAudit = (action: string, target: string, detail: string, actor = 'staging-admin') => audit.unshift({ id: randomUUID(), action, actor, target, detail, createdAt: new Date().toISOString() }); const getJob = (id: string) => jobs.find((item) => item.id === id);
  return {
    kind: 'memory' as const,
    async getUserByEmail(email) { return users.find((user) => user.email.trim().toLowerCase() === email.trim().toLowerCase() && user.active && user.membershipStatus === 'ACTIVE') || null; }, async createSession(userId) { const token = createSessionToken(); const expiresAt = sessionExpiresAt(); sessions.set(hashSessionToken(token), { userId, expiresAt }); return { token, expiresAt }; }, async getSessionUser(token) { const session = sessions.get(hashSessionToken(token)); if (!session || session.expiresAt < new Date()) return null; const user = users.find((item) => item.id === session.userId); return user && user.active && user.membershipStatus === 'ACTIVE' ? { id: user.id, workspaceId: user.workspaceId, email: user.email, displayName: user.displayName, role: user.role } : null; }, async revokeSession(token) { sessions.delete(hashSessionToken(token)); },
    async createAccountToken(input) { const account = users.find((user) => user.id === input.adminUserId && user.workspaceId === input.workspaceId && user.active); if (!account) throw new Error('account not found in this workspace'); for (const item of accountTokens.values()) { if (item.workspaceId === input.workspaceId && item.adminUserId === input.adminUserId && item.purpose === input.purpose && !item.usedAt) item.usedAt = new Date(); } const { token, tokenHash } = makeAccountToken(); const expiresAt = new Date(Date.now() + (input.ttlMs || ACCOUNT_TOKEN_TTL_MS)); accountTokens.set(tokenHash, { id: randomUUID(), workspaceId: input.workspaceId, adminUserId: input.adminUserId, purpose: input.purpose, expiresAt }); addAudit(input.purpose === 'INVITE' ? 'ACCOUNT_INVITE_ISSUED' : 'ACCOUNT_RESET_ISSUED', input.adminUserId, `${input.purpose === 'INVITE' ? 'Invitation' : 'Password reset'} link issued; expires ${expiresAt.toISOString()}`, input.actor); return { token, expiresAt: expiresAt.toISOString() }; },
    async consumeAccountToken(token, password) { const entry = accountTokens.get(hashAccountToken(token)); if (!entry || entry.usedAt || entry.expiresAt.getTime() <= Date.now()) throw new Error('account link is invalid or expired'); const account = users.find((user) => user.id === entry.adminUserId && user.workspaceId === entry.workspaceId && user.active); if (!account) throw new Error('account link is invalid or expired'); const purposeMismatch = (entry.purpose === 'INVITE' && account.membershipStatus !== 'INVITED') || (entry.purpose === 'RESET' && account.membershipStatus !== 'ACTIVE'); if (purposeMismatch) throw new Error('account link is invalid or expired'); account.passwordHash = await hashPassword(password); account.membershipStatus = 'ACTIVE'; entry.usedAt = new Date(); for (const [hash, session] of sessions) if (session.userId === account.id) sessions.delete(hash); addAudit(entry.purpose === 'INVITE' ? 'MEMBER_INVITE_ACCEPTED' : 'PASSWORD_RESET_COMPLETED', account.id, entry.purpose === 'INVITE' ? 'Invitation accepted and membership activated' : 'Password reset completed; existing sessions revoked', account.email); return { id: account.id, workspaceId: account.workspaceId, email: account.email, displayName: account.displayName, role: account.role }; },
    async listCampaigns() { return campaigns; }, async listOas() { return oas; }, async listCustomers() { return customers; }, async listJobs() { return [...jobs].sort((a, b) => a.scheduledAt.localeCompare(b.scheduledAt)); }, async listOutbox(_workspaceId, jobId) { return deliveries.filter((item) => !jobId || item.jobId === jobId); }, async listAudit() { return audit; }, async dashboard() { const counts: Record<string, number> = {}; jobs.forEach((job) => { counts[job.status] = (counts[job.status] || 0) + 1; }); return { mode: 'DRY_RUN' as const, counts, nextJob: jobs.find((job) => job.status === 'SCHEDULED' || job.status === 'RETRYABLE') || null }; },
    async addJob(input) { if (input.mode === 'LIVE') throw new Error('the memory repository cannot create LIVE jobs; it has no credential vault'); if (!campaigns.some((item) => item.id === input.campaignId && item.active)) throw new Error('campaignId is not an active staging campaign'); if (!oas.some((item) => item.id === input.oaId && item.enabled)) throw new Error('oaId is not an enabled staging OA in this workspace'); if (input.status === 'SCHEDULED') { const readiness = await this.getCampaignReadiness(input.campaignId, input.workspaceId, input.oaId); if (!readiness.canSchedule) throw new Error(`campaign is not ready: ${readiness.blockers.join(', ')}`); } const clientRequestKey = input.clientRequestKey ? `${input.workspaceId}:${input.clientRequestKey}` : ''; if (clientRequestKey) { const existing = getJob(jobClientKeys.get(clientRequestKey) || ''); if (existing) return existing; } const job: SchedulerJob = { id: randomUUID(), workspaceId: input.workspaceId, campaignId: input.campaignId, campaignRevisionId: revisions.get(input.campaignId)?.[0]?.id, oaId: input.oaId, scheduledAt: new Date(input.scheduledAt).toISOString(), timeZone: input.timeZone, availableAt: new Date(input.scheduledAt).toISOString(), mode: 'DRY_RUN', status: input.status, attempts: 0, idempotencyKey: randomUUID(), createdAt: new Date().toISOString() }; jobs.unshift(job); if (clientRequestKey) jobClientKeys.set(clientRequestKey, job.id); addAudit(input.status === 'DRAFT' ? 'SCHEDULE_DRAFT_CREATED' : 'SCHEDULE_CREATED', job.id, 'DRY_RUN job created', input.actor); return job; },
    async scheduleJob(id, actor) { const job = getJob(id); if (!job || job.status !== 'DRAFT') throw new Error('only draft jobs can be scheduled'); job.status = 'SCHEDULED'; addAudit('SCHEDULE_SCHEDULED', id, 'scheduler job scheduled', actor); return job; }, async pauseJob(id, actor) { const job = getJob(id); if (!job || !['DRAFT','SCHEDULED','RETRYABLE'].includes(job.status)) throw new Error('job not found or transition is not allowed'); job.status = 'PAUSED'; addAudit('SCHEDULE_PAUSED', id, 'scheduler job paused', actor); return job; }, async resumeJob(id, actor) { const job = getJob(id); if (!job || job.status !== 'PAUSED') throw new Error('only paused jobs can be resumed'); job.status = 'SCHEDULED'; addAudit('SCHEDULE_RESUMED', id, 'scheduler job resumed', actor); return job; }, async cancelJob(id, actor) { const job = getJob(id); if (!job || !['DRAFT','SCHEDULED','PAUSED','RETRYABLE'].includes(job.status)) throw new Error('job not found or transition is not allowed'); job.status = 'CANCELLED'; addAudit('SCHEDULE_CANCELLED', id, 'scheduler job cancelled', actor); return job; }, async retryJob(id, actor) { const job = getJob(id); if (!job || !['PAUSED','FAILED','RETRYABLE'].includes(job.status)) throw new Error('job is not retryable'); job.status = 'RETRYABLE'; job.availableAt = new Date().toISOString(); addAudit('SCHEDULE_RETRY', id, 'retry keeps the same idempotency key', actor); return job; }, async runDryRun(id, actor) { const job = getJob(id); if (!job || job.mode !== 'DRY_RUN' || !['DRAFT','SCHEDULED','RETRYABLE','FAILED'].includes(job.status)) throw new Error('job is missing, paused, cancelled, completed, or not a DRY_RUN job'); const now = new Date().toISOString(); job.status = 'SCHEDULED'; job.scheduledAt = now; job.availableAt = now; addAudit('DRY_RUN_ENQUEUED', id, 'dry-run queued through the outbox worker pipeline', actor); return job; },
    async claimDueJob(workerId, now = new Date(), jobId) { const job = jobs.find((item) => (!jobId || item.id === jobId) && ['SCHEDULED','RETRYABLE'].includes(item.status) && new Date(item.availableAt || item.scheduledAt) <= now && new Date(item.scheduledAt) <= now); if (!job) return null; job.status = 'CLAIMED'; job.attempts += 1; addAudit('WORKER_CLAIMED', job.id, `worker claimed ${job.id}`, workerId); return job; }, async markJobSending(id) { const job = getJob(id); if (!job || job.status !== 'CLAIMED') throw new Error('job claim is no longer owned by this worker'); job.status = 'SENDING'; return job; }, async markJobCompleted(id, workerId) { const job = getJob(id); if (!job || !['CLAIMED','SENDING'].includes(job.status)) throw new Error('job completion is no longer owned by this worker'); job.status = 'COMPLETED'; job.lastError = undefined; addAudit('WORKER_COMPLETED', id, 'Mock LINE adapter completed DRY_RUN; no outbound request', workerId); return job; }, async markJobFailure(id, workerId, error, retryAt) { const job = getJob(id); if (!job || !['CLAIMED','SENDING'].includes(job.status)) throw new Error('job claim is no longer owned by this worker'); job.status = retryAt ? 'RETRYABLE' : 'FAILED'; job.availableAt = retryAt?.toISOString() || job.availableAt; job.lastError = error; addAudit(retryAt ? 'WORKER_RETRY' : 'WORKER_FAILED', id, error, workerId); return job; }, async prepareOutbox(jobId) { const job = getJob(jobId); if (!job || !job.workspaceId) throw new Error('scheduler job not found'); let delivery = deliveries.find((item) => item.jobId === jobId); if (!delivery) { delivery = { id: randomUUID(), workspaceId: job.workspaceId, jobId, oaId: job.oaId, recipientKey: '__campaign__', idempotencyKey: job.idempotencyKey, lineRetryKey: job.idempotencyKey, status: 'PENDING', attempts: 0, createdAt: new Date().toISOString(), updatedAt: new Date().toISOString() }; deliveries.push(delivery); } return [delivery]; }, async getDeliveryContext(deliveryId, workspaceId) { const delivery = deliveries.find((item) => item.id === deliveryId && item.workspaceId === workspaceId); const job = delivery && getJob(delivery.jobId); const revision = job?.campaignRevisionId ? [...revisions.values()].flat().find((item) => item.id === job.campaignRevisionId) : undefined; if (!delivery || !job || !revision) throw new Error('outbox delivery not found in this workspace'); return { jobId: delivery.jobId, workspaceId: delivery.workspaceId, oaId: delivery.oaId, campaignRevisionId: revision.id, recipientKey: delivery.recipientKey, flexJson: revision.flexJson }; }, async reserveDeliverySlot(input) { const oa = oas.find((item) => item.id === input.oaId && item.enabled); if (!oa) throw new OaPolicyError('OA_NOT_AVAILABLE', 'selected staging OA is not available'); const now = input.now || new Date(); const windowStartedAt = new Date(Math.floor(now.getTime() / 60_000) * 60_000).toISOString(); const window = rateWindows.get(input.oaId); const used = window?.windowStartedAt === windowStartedAt ? window.used : 0; if (used >= oa.quotaPerMinute) throw new OaPolicyError('RATE_LIMITED', 'OA per-minute delivery limit reached', true); if (input.count) rateWindows.set(input.oaId, { windowStartedAt, used: used + 1 }); return { windowStartedAt: input.count ? windowStartedAt : null, counted: input.count }; }, async releaseDeliverySlot(input) { if (!input.windowStartedAt) return; const window = rateWindows.get(input.oaId); if (window?.windowStartedAt === input.windowStartedAt) window.used = Math.max(0, window.used - 1); }, async reconcileOutboxDelivery(input) { const delivery = deliveries.find((item) => item.id === input.deliveryId && item.jobId === input.jobId && item.workspaceId === input.workspaceId); if (!delivery || delivery.status !== 'UNKNOWN') throw new Error('only UNKNOWN deliveries can be reconciled'); delivery.status = input.status; delivery.lastError = input.status === 'SENT' ? undefined : 'operator marked failed after UNKNOWN'; delivery.updatedAt = new Date().toISOString(); addAudit('OUTBOX_RECONCILED', delivery.id, `operator reconciled UNKNOWN delivery as ${input.status}`, input.actor); return delivery; }, async markOutboxSending(id, workerId) { const delivery = deliveries.find((item) => item.id === id); const job = delivery && getJob(delivery.jobId); if (!delivery || !job || job.status !== 'SENDING' || delivery.status === 'SENT') throw new Error('outbox delivery is no longer owned by this worker'); delivery.status = 'SENDING'; delivery.attempts += 1; delivery.updatedAt = new Date().toISOString(); addAudit('OUTBOX_SENDING', id, `worker ${workerId}`, workerId); return delivery; }, async markOutboxCompleted(id, workerId, result) { const delivery = deliveries.find((item) => item.id === id); if (!delivery || delivery.status !== 'SENDING') throw new Error('outbox completion is no longer owned by this worker'); delivery.status = 'SENT'; delivery.providerStatus = result.providerStatus; delivery.providerRequestId = result.providerRequestId; delivery.lastError = undefined; delivery.updatedAt = new Date().toISOString(); addAudit('OUTBOX_SENT', id, `worker ${workerId}`, workerId); return delivery; }, async markOutboxFailure(id, workerId, error, status, result = {}) { const delivery = deliveries.find((item) => item.id === id); if (!delivery || delivery.status !== 'SENDING') throw new Error('outbox failure is no longer owned by this worker'); delivery.status = status; delivery.providerStatus = result.providerStatus; delivery.providerRequestId = result.providerRequestId; delivery.lastError = error; delivery.updatedAt = new Date().toISOString(); addAudit('OUTBOX_' + status, id, error, workerId); return delivery; }, async recoverStaleJobs() { return 0; },
    async listRevisions(campaignId) { return revisions.get(campaignId) || []; }, async createRevision(campaignId, flexJson, actor) { const list = revisions.get(campaignId); if (!list) throw new Error('campaign not found'); const revision: CampaignRevision = { id: randomUUID(), campaignId, revision: list.length + 1, flexJson, state: 'DRAFT', createdBy: actor, createdAt: new Date().toISOString() }; list.unshift(revision); const campaign = campaigns.find((item) => item.id === campaignId)!; campaign.flexJson = flexJson; campaign.latestRevision = revision.revision; addAudit('FLEX_REVISION_CREATED', campaignId, `revision ${revision.revision}`, actor); return revision; }, async acceptWebhook(input) { const key = `${input.oaId}:${input.eventId}`; const duplicate = webhookEvents.has(key); webhookEvents.add(key); const oa = oas.find((item) => item.id === input.oaId); if (!duplicate && oa && input.lineUserKey && input.eventType === 'follow') { const existing = customers.find((item) => item.providerId === oa.providerId && item.lineUserKey === input.lineUserKey); if (existing) { existing.optIn = true; existing.blockedAt = undefined; } else customers.push({ id: randomUUID(), providerId: oa.providerId, lineUserKey: input.lineUserKey, optIn: true }); } if (!duplicate && oa && input.lineUserKey && input.eventType === 'unfollow') { const existing = customers.find((item) => item.providerId === oa.providerId && item.lineUserKey === input.lineUserKey); if (existing) { existing.optIn = false; existing.blockedAt = new Date().toISOString(); } else customers.push({ id: randomUUID(), providerId: oa.providerId, lineUserKey: input.lineUserKey, optIn: false, blockedAt: new Date().toISOString() }); } return { accepted: true, duplicate }; },
    async createOa(input) { const oa: OaIntegration = { id: randomUUID(), displayName: input.displayName, basicId: input.basicId, providerId: input.providerId, environment: 'STAGING', enabled: false, secretConfigured: false, connectionStatus: 'NOT_CONFIGURED', credentialStatus: 'NOT_CONFIGURED', quotaPerMinute: 60, killSwitch: false }; oas.push(oa); addAudit('OA_CONNECTION_CREATED', oa.id, 'Staging OA metadata created without credentials', input.actor); return oa; },
    async validateOa(id, _workspaceId, actor) { const oa = oas.find((item) => item.id === id); if (!oa) throw new Error('staging OA not found'); oa.connectionStatus = 'DRY_RUN_READY'; oa.credentialStatus = 'NOT_CONFIGURED'; addAudit('OA_CREDENTIAL_REFERENCE_VALIDATED', id, 'No provider call was made', actor); return oa; },
    async setOaKillSwitch(id, _workspaceId, enabled, reason, actor) { const oa = oas.find((item) => item.id === id); if (!oa) throw new Error('staging OA not found'); oa.killSwitch = enabled; oa.killSwitchReason = reason; addAudit(enabled ? 'OA_KILL_SWITCH_ON' : 'OA_KILL_SWITCH_OFF', id, reason, actor); return oa; }, async setOaEnabled(id, _workspaceId, enabled, actor) { const oa = oas.find((item) => item.id === id); if (!oa) throw new Error('staging OA not found'); oa.enabled = enabled; addAudit(enabled ? 'OA_ENABLED' : 'OA_DISABLED', id, 'Staging OA enabled state changed', actor); return oa; },
    async setSystemKillSwitch(_workspaceId, enabled, reason, actor) { systemKillSwitch = enabled; addAudit(enabled ? 'SYSTEM_KILL_SWITCH_ON' : 'SYSTEM_KILL_SWITCH_OFF', 'memory-workspace', reason, actor); return { enabled, reason }; },
    async setCampaignKillSwitch(campaignId, _workspaceId, enabled, reason, actor) { const control = campaignControls.get(campaignId); if (!control) throw new Error('campaign not found'); control.killSwitch = enabled; addAudit(enabled ? 'CAMPAIGN_KILL_SWITCH_ON' : 'CAMPAIGN_KILL_SWITCH_OFF', campaignId, reason, actor); return this.getCampaignReadiness(campaignId, 'memory-workspace'); },
    async validateCampaign(campaignId, _workspaceId, actor) { const control = campaignControls.get(campaignId); if (!control) throw new Error('campaign not found'); control.approvalStatus = 'VALIDATED'; addAudit('CAMPAIGN_VALIDATED', campaignId, 'Preview and validation completed', actor); return this.getCampaignReadiness(campaignId, 'memory-workspace'); },
    async approveCampaign(campaignId, _workspaceId, actor) { const control = campaignControls.get(campaignId); if (!control || control.approvalStatus !== 'VALIDATED') throw new Error('campaign must be validated before approval'); control.approvalStatus = 'APPROVED'; addAudit('CAMPAIGN_APPROVED', campaignId, 'Campaign approved for Staging DRY_RUN scheduling', actor); return this.getCampaignReadiness(campaignId, 'memory-workspace'); },
    async getCampaignReadiness(campaignId, _workspaceId, oaId) { const control = campaignControls.get(campaignId); const oa = oas.find((item) => item.id === oaId) || oas.find((item) => item.enabled); if (!control || !oa) throw new Error('campaign readiness not found'); const eligible = customers.filter((item) => item.providerId === oa.providerId && item.optIn && !item.blockedAt).length; const optedOut = customers.filter((item) => item.providerId === oa.providerId && !item.optIn).length; const blocked = customers.filter((item) => item.providerId === oa.providerId && item.blockedAt).length; const blockers = control.approvalStatus === 'APPROVED' ? [] : ['Campaign approval is required']; if (systemKillSwitch) blockers.push('System kill switch is active'); if (oa.killSwitch) blockers.push('OA kill switch is active'); if (control.killSwitch) blockers.push('Campaign kill switch is active'); if (!oa.enabled) blockers.push('Selected OA is not an enabled staging OA'); return { campaignId, approvalStatus: control.approvalStatus, systemKillSwitch, oaKillSwitch: oa.killSwitch, campaignKillSwitch: control.killSwitch, quota: { limitPerMinute: oa.quotaPerMinute, usedInWindow: 0, remaining: oa.quotaPerMinute }, audience: { eligible, optedOut, blocked }, canSchedule: blockers.length === 0, blockers }; }
  };
}

